  gSignerCert = null;
  gEncryptionCert = null;
  gSignatureAlgorithm = "";
  gDigestAlgorithm = "";
  gContentEncAlgorithm = "";
  gContentEncKeyBits = 0;
  gKeyEncAlgorithm = "";

  setMessageCryptoBox(null, null, null, false);
  clearCryptoDetails();

  forgetEncryptedURI();
  onMessageSecurityPopupHidden();
}
